// 1) Check the HMAC signature on the RAW body (same bytes Python signed).
// 2) Check the fields we need are there.
const crypto = require('crypto');
const cfg = $('Config').first().json;
const req = $('Signal webhook').first().json;

const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const got = String(req.headers['x-signature'] || '');
const expected = crypto.createHmac('sha256', cfg.webhook_secret).update(raw).digest('hex');

let ok = got.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected));
if (!ok) {
  return [{ json: { valid: false, http_status: 401, error: 'bad signature' } }];
}

let p;
try { p = JSON.parse(raw.toString('utf8')); }
catch (e) { return [{ json: { valid: false, http_status: 400, error: 'invalid json' } }]; }

const required = ['event', 'source', 'board_token', 'external_id', 'title', 'company_name', 'company_domain'];
const missing = required.filter(f => !p[f]);
if (missing.length) {
  return [{ json: { valid: false, http_status: 400, error: 'missing fields', fields: missing } }];
}

// Clean the domain so "https://www.UserGems.com/" and "usergems.com" match.
const domain = String(p.company_domain).toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim();

const key = req.headers['x-idempotency-key'] ||
  `${p.source}:${p.board_token}:${p.external_id}:${p.event}`;

return [{ json: { valid: true, http_status: 200, key, domain, signal: p } }];

// The routing rule, written down in one place.
// Four signal types (each one has an owner, an action, and a window):
//   revenue_leader   -> AE owner,      HIGH,   act within 2 days
//   marketing_leader -> AE owner,      MEDIUM, act within 3 days
//   funding_round    -> AE owner,      MEDIUM, act within 3 days  (event 'money_raised', SEC Form D)
//   review           -> triage owner,  LOW,    look within 5 days
// "review" = regional/country heads or anything the rule isn't sure about.
// A money_raised event is decided by the detector's funding rule, not the title.
const v = $input.first().json;
const t = ' ' + String(v.signal.title).toLowerCase().replace(/[^a-z0-9]+/g, ' ') + ' ';

const regional = /( emea | apac | anz | dach | uki | uk | latam | amer | japan | india | north america | europe | regional | region )/;
const revenue = /( sales | revenue | cro | chief revenue | gtm | go to market | commercial )/;
const marketing = /( marketing | growth | demand | cmo | brand )/;

let type = 'review';
if (v.signal.event === 'money_raised') type = 'funding_round';
else if (regional.test(t)) type = 'review';
else if (revenue.test(t)) type = 'revenue_leader';
else if (marketing.test(t)) type = 'marketing_leader';

const plays = {
  revenue_leader:   { priority: 'HIGH',   due_days: 2, label: 'New revenue leader' },
  marketing_leader: { priority: 'MEDIUM', due_days: 3, label: 'New marketing/growth leader' },
  funding_round:    { priority: 'MEDIUM', due_days: 3, label: 'New funding round' },
  review:           { priority: 'LOW',    due_days: 5, label: 'Needs a human look' },
};
return [{ json: { ...v, signal_type: type, play: plays[type] } }];

// Decide: is this company new, already in HubSpot, or is this signal a repeat?
// Also decide the owner, and say why (so nobody has to guess later).
const cfg = $('Config').first().json;
const r = $('Route rule').first().json;
const found = ($input.first().json.results || [])[0] || null;

if (found && found.properties && found.properties.gtm_signal_key === r.key) {
  return [{ json: { ...r, action: 'duplicate', company_id: found.id } }];
}

const existingOwner = found && found.properties ? found.properties.hubspot_owner_id : null;
let owner = null, note = '';
if (existingOwner) {
  owner = existingOwner;
  note = 'Kept the owner already on the company record';
} else {
  const wanted = r.signal_type === 'review' ? cfg.triage_owner_id : cfg.ae_owner_id;
  if (wanted) {
    owner = String(wanted);
    note = r.signal_type === 'review' ? 'No owner yet. Sent to triage by rule' : 'No owner yet. Assigned to AE by rule';
  } else {
    owner = String(cfg.triage_owner_id);
    note = 'MISSING OWNER: rule had no AE set, fell back to triage';
  }
}
return [{ json: { ...r, action: found ? 'update' : 'create', company_id: found ? found.id : null, owner_id: owner, routing_note: note } }];

// Enrich: one cheap public check. Does the homepage load a HubSpot,
// Marketo or Pardot tracking script? It's a hint, not proof
// (lots of sites load these through Google Tag Manager, which we can't see).
const d = $('Decide').first().json;
const res = $input.first().json || {};
const html = String(res.data || res.body || '');
let hint = 'not_checked';
if (html.length > 500) {
  if (/js\.hs-scripts\.com|js\.hsforms\.net|js\.hs-analytics\.net/i.test(html)) hint = 'hubspot';
  else if (/munchkin\.marketo\.net|munchkin\.js|Munchkin\.init/i.test(html)) hint = 'marketo';
  else if (/pi\.pardot\.com|piAId/i.test(html)) hint = 'pardot';
  else hint = 'none_found';
}
const today = new Date();
const addDays = n => { const x = new Date(today); x.setUTCDate(x.getUTCDate() + n); return x; };
const ymd = x => x.toISOString().slice(0, 10);
const cfg = $('Config').first().json;
const s = d.signal;
const signalDate = (s.first_published || s.detected_at || ymd(today)).slice(0, 10);

const properties = {
  name: s.company_name,
  domain: d.domain,
  hubspot_owner_id: d.owner_id,
  gtm_signal_type: d.signal_type,
  gtm_signal_title: s.title,
  gtm_signal_url: s.source_url || '',
  gtm_signal_date: signalDate,
  gtm_signal_key: d.key,
  gtm_signal_status: 'new',
  gtm_signal_expires: ymd(addDays(Number(cfg.signal_expiry_days))),
  marketing_stack_hint: hint,
  gtm_routing_note: d.routing_note,
};
// On an existing record, don't overwrite the name/domain/owner someone already set.
if (d.action === 'update') {
  delete properties.name;
  delete properties.domain;
  if (d.routing_note.startsWith('Kept')) delete properties.hubspot_owner_id;
}
const stackText = { hubspot: 'Homepage loads HubSpot tracking', marketo: 'Homepage loads Marketo', pardot: 'Homepage loads Pardot', none_found: 'No HubSpot/Marketo/Pardot script found on homepage', not_checked: 'Homepage not checked' }[hint];
const task = {
  hs_task_subject: `${d.play.label}: ${s.title} at ${s.company_name}`,
  hs_task_body: [
    s.event === 'money_raised'
      ? `Signal: ${s.company_name} filed an SEC Form D: ${s.title} (${signalDate}). Fresh money usually means new GTM spend.`
      : `Signal: ${s.company_name} posted "${s.title}" (${signalDate}).`,
    `Evidence: ${s.source_url || 'no url'}`,
    `Stack hint: ${stackText}.`,
    `Why you: ${d.routing_note}.`,
    `Next step: decide the play within ${d.play.due_days} days, or mark the company "No action" with a reason.`,
    `Signal expires: ${properties.gtm_signal_expires}.`,
  ].join('\n'),
  hs_task_priority: d.play.priority,
  hs_task_status: 'NOT_STARTED',
  hs_task_type: 'TODO',
  hs_timestamp: addDays(d.play.due_days).toISOString(),
  hubspot_owner_id: d.owner_id,
};
return [{ json: { ...d, hint, properties, task } }];

// Whichever branch ran (create or update), grab the company id.
const e = $('Enrich + build records').first().json;
return [{ json: { ...e, company_id: $input.first().json.id } }];
